scwin.vScrenID = "ULDINS25000.xml";
scwin.isurCnt = 0;
scwin.chgCnt = 0;
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};



/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 다운로드  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    // 발행기관 체크
    if ($c.stf.getObjectValue(txb_FROM_ISUR_CD) > $c.stf.getObjectValue(txb_TO_ISUR_CD)) {
        $c.win.alert("검색시작 발행기관코드가 검색종료 발행기관코드보다 큽니다.");
        txb_FROM_ISUR_CD.focus();
        return false;
    }

    // 코드부여일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) == false) {
        return false;
    }

    //데이터셋 초기화
    dts_List.removeAll();
    tab_IsurInfo.setSelectedTabIndex("1");
    $c.cm.ShowWin(panel_3);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.src = "../img/btn_select_d.gif";
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS25000_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.download.select.listDownloadIsurInfoInquiry" + "&{P}ISUR_CD_FROM=" + $c.stf.getObjectValue(txb_FROM_ISUR_CD) + "&{P}ISUR_CD_TO=" + $c.stf.getObjectValue(txb_TO_ISUR_CD) + "&{P}ISUR_KND=" + $c.stf.getObjectValue(cmb_ISUR_KND) + "&{P}ISUR_KND_OP=" + $c.stf.getObjectValue(cmb_Oper1) + "&{P}ACNTCLS_MMDD1=" + $c.stf.getObjectValue(cmb_ACNTCLS_MMDD1) + "&{P}ACNTCLS_MMDD1_OP=" + $c.stf.getObjectValue(cmb_Oper2) + "&{P}COM_ATTR_TP=" + $c.stf.getObjectValue(cmb_COM_ATTR_TP_CD) + "&{P}COM_ATTR_TP_OP=" + $c.stf.getObjectValue(cmb_Oper3) + "&{P}MKT_TP=" + $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) + "&{P}MKT_TP_OP=" + $c.stf.getObjectValue(cmb_Oper4) + "&{P}LIST_STAT=" + $c.stf.getObjectValue(cmb_LIST_STAT_CD) + "&{P}LIST_STAT_OP=" + $c.stf.getObjectValue(cmb_Oper5) + "&{P}ACTIV_YN=" + $c.stf.getObjectValue(cmb_ACTIV_YN) + "&{P}ISUR_APPL_DD_FROM=" + $c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) + "&{P}ISUR_APPL_DD_TO=" + $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_search_chg
 * 설명       : 회사명 변경내역  목록 조회한다.
 ***********************************************/
scwin.ins_search_chg = function() {
    // 발행기관 체크
    if ($c.stf.getObjectValue(txb_FROM_ISUR_CD) > $c.stf.getObjectValue(txb_TO_ISUR_CD)) {
        $c.win.alert("검색시작 발행기관코드가 검색종료 발행기관코드보다 큽니다.");
        txb_FROM_ISUR_CD.focus();
        return false;
    }

    //데이터셋 초기화
    dts_ChgList.removeAll();
    tab_IsurInfo.setSelectedTabIndex("2");
    $c.cm.ShowWin(panel_3); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS25000_CHGLIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.download.select.listDownloadIsurChgInfoInquiry" + "&{P}param01=" + txb_FROM_ISUR_CD.getValue() + "&{P}param02=" + txb_TO_ISUR_CD.getValue();
    dts_ChgList.DataID = encodeURI(url);
    dts_ChgList.reset();
};



/********************************************** 
 * 함수명   : fn_GridCtrl
 * 설명       : 체크박스 체크 시 그리드 항목 show
 ***********************************************/
scwin.fn_GridCtrl = function(pObj) {
    var sColId = pObj.id;
    sColId = sColId.replace("ckb_", "");
    var bChecked = $c.stf.getObjectValue(pObj);
    if (bChecked == "Y" && $c.cm.getColumnProp(grd_Grid, sColId, "Show") != "TRUE") {
        $c.cm.setColumnProp(grd_Grid, sColId, "Show", true);
    } else if (bChecked == "N" && $c.cm.getColumnProp(grd_Grid, sColId, "Show") == "TRUE") {
        $c.cm.setColumnProp(grd_Grid, sColId, "Show", false);
    }
    //grd_Grid.AutoResizeAllCol(true);

};




/********************************************** 
 * 함수명   : fn_AllStandardCheck
 * 설명       : 전체선택 체크 시 나머지 모두 언체크.
 ***********************************************/
scwin.fn_AllCheck = function() {
    if ($c.stf.getObjectValue(ckb_ALL) == "Y") {
        $c.stf.setObjectValue(ckb_StandardALL, "Y");
        scwin.fn_AllStandardCheck();
        $c.stf.setObjectValue(ckb_UniqueALL, "Y");
        scwin.fn_AllUniqueCheck();
    } else {
        $c.stf.setObjectValue(ckb_StandardALL, "N");
        scwin.fn_AllStandardCheck();
        $c.stf.setObjectValue(ckb_UniqueALL, "N");
        scwin.fn_AllUniqueCheck();
    }
};





/********************************************** 
 * 함수명   : fn_AllStandardCheck
 * 설명       : 전체선택 체크 시 체크.
 ***********************************************/
scwin.fn_AllStandardCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(ckb_StandardALL);
    var oCheckBoxs = document.getElementsByName("std_ckb");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};




/********************************************** 
 * 함수명   : fn_AllUniqueCheck
 * 설명       : 고유정보 체크 시 체크.
 ***********************************************/
scwin.fn_AllUniqueCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(ckb_UniqueALL);
    var oCheckBoxs = document.getElementsByName("ckb");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};




/********************************************** 
 * 함수명   : fn_AllStdCheck
 * 설명       : 기본정보 체크 시 체크.
 ***********************************************/
scwin.fn_AllStdCheck = function() {
    var oCheckBoxs = document.getElementsByName("std_ckb");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};
scwin.showAll = function() {
    $c.cm.setColumnProp(grd_Grid, "ISUR_CD", "Show", true); //  발행기관코드 vv
    $c.cm.setColumnProp(grd_Grid, "COM_NM", "Show", true); //  회사명 vv
    $c.cm.setColumnProp(grd_Grid, "COM_ENG_NM", "Show", true); //  회사영문명 vv
    $c.cm.setColumnProp(grd_Grid, "CORP_REG_NO", "Show", true); //  법인등록번호 vv
    $c.cm.setColumnProp(grd_Grid, "BZ_REG_NO", "Show", true); //  사업자등록번호 vv
    $c.cm.setColumnProp(grd_Grid, "FSS_UNQ_NO", "Show", true); //  금감원고유번호 vv
    $c.cm.setColumnProp(grd_Grid, "COM_ATTR_TP_CD", "Show", true); //  회사속성구분코드
    $c.cm.setColumnProp(grd_Grid, "FOUND_DD", "Show", true); //  설립일자 vv
    $c.cm.setColumnProp(grd_Grid, "ACNTCLS_MMDD1", "Show", true); //  결산월일1
    $c.cm.setColumnProp(grd_Grid, "BND_LIST_CORP_YN", "Show", true); //  채권상장법인여부
    $c.cm.setColumnProp(grd_Grid, "SPOT_ISU_TRD_MKT_TP_CD", "Show", true); //  현물종목거래시장구분코드
    $c.cm.setColumnProp(grd_Grid, "LIST_STAT_CD", "Show", true); //  상장상태코드
    $c.cm.setColumnProp(grd_Grid, "ACTIV_YN", "Show", true); //  활성여부 v
    $c.cm.setColumnProp(grd_Grid, "ISUR_SYMBL", "Show", true); //  발행기관심볼 vv
    $c.cm.setColumnProp(grd_Grid, "CORP_TEL_NO", "Show", true); //  법인전화번호 vv
    $c.cm.setColumnProp(grd_Grid, "CEO_NM", "Show", true); //  대표이사명 vv
    $c.cm.setColumnProp(grd_Grid, "GOVBND_ISUR_CD", "Show", true); //  국채발행체코드 vv
    $c.cm.setColumnProp(grd_Grid, "MUNIBND_ISUR_CD", "Show", true); //  지방채발행체코드 vv
    $c.cm.setColumnProp(grd_Grid, "SPECLBND_ISUR_CD", "Show", true); //  특수채발행체코드 vv
    $c.cm.setColumnProp(grd_Grid, "BENFCERT_ISUR_CD", "Show", true); //  수익증권발행체코드 vv

    /* 2016.10.07 delete 
    grd_Grid.setColumnProp("APCT_BELNG_COM_NM", "Show",true);         //신청자회사명
    grd_Grid.setColumnProp("APCT_NM", "Show",true);         //신청자
    grd_Grid.setColumnProp("APCT_TEL_NO", "Show",true);         //신청자전화번호(내선)
    grd_Grid.setColumnProp("APCT_FAX_NO", "Show",true);         //신청자팩스번호
    grd_Grid.setColumnProp("ENCRYP_APCT_EMAIL", "Show",true);         //신청자이메일
    */
    $c.cm.setColumnProp(grd_Grid, "CHRG_NM", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "BELNG_DEP_NM", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "JOBTITL_NM", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "CHRG_TEL_NO", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "CELLPHONE_NO", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "CHRG_FAX_NO", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "CHRG_EMAIL", "Show", true);
    $c.cm.setColumnProp(grd_Grid, "STD_CD_MEMO", "Show", true); //  표준코드메모

};
scwin.gform_onload = function() {
    $c.stf.showObj(panel_5, false);
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    fn_CtrlBtn("no_data");
    ins_combo_set(dts_SPOT_ISU_TRD_MKT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "01213", "ALL"); // 현물종목거래시장구분코드
    ins_combo_set(dts_LIST_STAT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00714", "ALL"); // 00714 - 시장구분 

    ins_combo_set(dts_COM_ATTR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00840", "ALL"); // 회사속성

    $c.stf.setObjectValue(ckb_StandardALL, "Y");
    scwin.fn_AllStandardCheck();
    $c.stf.showObj(label_19, false);
    $c.stf.showObj(ckb_UniqueALL, false);
    var array_grid = [grd_Grid, grd_Grid2];
    setResizeGrid(array_grid, 310);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (rowcount == 0) {
        btn_excelsave.setDisabled(true);
        btn_excelsave.src = "../img/btn_excelsave_d.gif";
    } else {
        btn_excelsave.setDisabled(false);
        btn_excelsave.src = "../img/btn_excelsave.gif";
    }
    scwin.isurCnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(false);
    btn_search.src = "../img/btn_select.gif";
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.isurCnt = 0;
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.btn_excelsave_onclick = function() {
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "";
    var xls_path = "";
    if (tab_IsurInfo.getSelectedTabIndex() == "1") {
        if (scwin.isurCnt == 0) {
            $c.win.alert("해당 데이터가 없습니다.\n 조회를 먼저 실행하십시요");
            return;
        }
        title = "발행기관 다운로드";
        xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
        $c.data.downloadGridViewOffice(grd_Grid, title, xls_path, 8, 0);
        //grd_Grid.GridToExcel(title, "", "8");

    } else if (tab_IsurInfo.getSelectedTabIndex() == "2") {
        if (scwin.chgCnt == 0) {
            $c.win.alert("해당 데이터가 없습니다.\n 조회를 먼저 실행하십시요");
            return;
        }
        title = "회사명 변경내역 다운로드";
        xls_path = "c:\\isinDownload\\" + today + "_" + title + ".xls";
        $c.data.downloadGridViewOffice(grd_Grid2, title, xls_path, 8, 0);
        //grd_Grid2.GridToExcel(title, "", "8");

    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
};
scwin.dts_ChgList_OnLoadCompleted = function(rowcount) {
    if (dts_ChgList.errorMsg) {
        $c.win.alert(dts_ChgList.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (rowcount == 0) {
        btn_excelsave.setDisabled(true);
        btn_excelsave.src = "../img/btn_excelsave_d.gif";
    } else {
        btn_excelsave.setDisabled(false);
        btn_excelsave.src = "../img/btn_excelsave.gif";
    }
    scwin.chgCnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid2); //데이터 로딩중닫기 및 조회없음 처리

};
